package com.dixitdada.journalApp.service; import com.dixitdada.journalApp.dto.RegisterRequest; import com.dixitdada.journalApp.entity.User; import com.dixitdada.journalApp.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.List; @Service @RequiredArgsConstructor public class UserService { private final UserRepository repo; private final PasswordEncoder encoder; public User register(RegisterRequest r){if(repo.existsByUsername(r.username()))throw new IllegalArgumentException("Username already exists");return repo.save(User.builder().username(r.username()).password(encoder.encode(r.password())).email(r.email()).build());} public User get(String n){return repo.findByUsername(n).orElseThrow();} public List<User> all(){return repo.findAll();} public void delete(String n){repo.findByUsername(n).ifPresent(repo::delete);} }